function readStudents() {
  try {
    if (fs.existsSync(STUDENTS_FILE)) {
      const content = fs.readFileSync(STUDENTS_FILE, "utf-8");
      const list = JSON.parse(content);
      let changed = false;
      list.forEach((s: any) => {
        if (!s.password) {
          s.password = "123456";
          changed = true;
        }
        if (!s.activationStartDate) {
          s.activationStartDate = new Date().toISOString().split('T')[0];
          changed = true;
        }
        if (!s.activationEndDate) {
          const future = new Date();
          future.setDate(future.getDate() + 30);
          s.activationEndDate = future.toISOString().split('T')[0];
          changed = true;
        }
      });
      if (changed) {
        fs.writeFileSync(STUDENTS_FILE, JSON.stringify(list, null, 2), "utf-8");
      }
      return list;
    }
  } catch (e) {
    console.error("Error reading students file, resetting to seed", e);
  }
  const seeded = DEFAULT_STUDENTS.map(s => {
    const today = new Date().toISOString().split('T')[0];
    const future = new Date();
    future.setDate(future.getDate() + 30);
    return { 
      ...s, 
      password: "123456",
      activationStartDate: today,
      activationEndDate: future.toISOString().split('T')[0]
    };
  });
  fs.writeFileSync(STUDENTS_FILE, JSON.stringify(seeded, null, 2), "utf-8");
  return seeded;
}

function writeStudents(students: any[]) {
  try {
    fs.writeFileSync(STUDENTS_FILE, JSON.stringify(students, null, 2), "utf-8");
  } catch (e) {
    console.error("Error writing students file", e);
  }
}

function readSettings() {
  try {
    if (fs.existsSync(SETTINGS_FILE)) {
      const content = fs.readFileSync(SETTINGS_FILE, "utf-8");
      return JSON.parse(content);
    }
  } catch (e) {
    console.error("Error reading settings file, resetting to default", e);
  }
  fs.writeFileSync(SETTINGS_FILE, JSON.stringify(DEFAULT_SETTINGS, null, 2), "utf-8");
  return DEFAULT_SETTINGS;
}

function writeSettings(settings: any) {
  try {
    fs.writeFileSync(SETTINGS_FILE, JSON.stringify(settings, null, 2), "utf-8");
  } catch (e) {
    console.error("Error writing settings file", e);
  }
}

function readSupportMessages() {
  try {
    if (fs.existsSync(SUPPORT_MESSAGES_FILE)) {
      const content = fs.readFileSync(SUPPORT_MESSAGES_FILE, "utf-8");
      return JSON.parse(content);
    }
  } catch (e) {
    console.error("Error reading support messages file", e);
  }
  return [];
}

function writeSupportMessages(messages: any[]) {
  try {
    fs.writeFileSync(SUPPORT_MESSAGES_FILE, JSON.stringify(messages, null, 2), "utf-8");
  } catch (e) {
    console.error("Error writing support messages file", e);
  }
}

