app.post("/api/students/login", (req, res) => {
  const { email, password } = req.body;
  if (!email || !password) {
    return res.status(400).json({ error: "البريد الإلكتروني وكلمة المرور مطلوبان." });
  }
  const students = readStudents();
  const student = students.find(
    (s: any) => s.email?.toLowerCase() === email.trim().toLowerCase() && s.password === password
  );
  if (student) {
    res.json({ success: true, student });
  } else {
    res.status(401).json({ error: "البريد الإلكتروني أو كلمة المرور غير صحيحة." });
  }
});

app.post("/api/students/register", (req, res) => {
  const newStudent = req.body;
  if (!newStudent.name || !newStudent.phone || !newStudent.email || !newStudent.password) {
    return res.status(400).json({ error: "جميع الحقول مطلوبة بما فيها كلمة المرور." });
  }
  const students = readStudents();
  // Check email
  const emailExists = students.some(
    (s: any) => s.email?.toLowerCase() === newStudent.email.trim().toLowerCase()
  );
  if (emailExists) {
    return res.status(400).json({ error: "هذا البريد الإلكتروني مسجل بالفعل. يرجى تسجيل الدخول." });
  }
  // Check phone
  const phoneExists = students.some((s: any) => s.phone === newStudent.phone.trim());
  if (phoneExists) {
    return res.status(400).json({ error: "رقم الهاتف هذا مسجل بالفعل. يرجى تسجيل الدخول." });
  }

  const today = new Date().toISOString().split('T')[0];
  const future = new Date();
  future.setDate(future.getDate() + 30);

  const studentToSave = {
    completedLessons: [],
    passedQuizzes: {},
    submittedProjects: [],
    bookmarkedLessons: [],
    notes: {},
    xp: 100, // Gift 100 XP
    activationStartDate: today,
    activationEndDate: future.toISOString().split('T')[0],
    ...newStudent,
    email: newStudent.email.trim(),
    phone: newStudent.phone.trim()
  };

  students.push(studentToSave);
  writeStudents(students);
  res.json({ success: true, student: studentToSave });
});

app.post("/api/students", (req, res) => {
  const newStudent = req.body;
  if (!newStudent.phone) {
    return res.status(400).json({ error: "Phone number is required." });
  }
  const students = readStudents();
  const index = students.findIndex((s: any) => s.phone === newStudent.phone);
  if (index >= 0) {
    // Preserve password and other fields not provided in sync
    students[index] = { ...students[index], ...newStudent };
  } else {
    students.push(newStudent);
  }
  writeStudents(students);
  res.json({ success: true, student: students[index >= 0 ? index : students.length - 1] });
});

app.put("/api/students/:phone", (req, res) => {
  const phone = req.params.phone;
  const updatedData = req.body;
  const students = readStudents();
  const index = students.findIndex((s: any) => s.phone === phone);
  if (index >= 0) {
    students[index] = { ...students[index], ...updatedData };
    writeStudents(students);
    res.json({ success: true, student: students[index] });
  } else {
    res.status(404).json({ error: "Student not found." });
  }
});

app.delete("/api/students/:phone", (req, res) => {
  const phone = req.params.phone;
  const students = readStudents();
  const filtered = students.filter((s: any) => s.phone !== phone);
  writeStudents(filtered);
  res.json({ success: true });
});

