// AI Coach Activation Key Management APIs
app.get("/api/ai-coach/keys", (req, res) => {
  const settings = readSettings();
  const keys = settings.aiCoachKeys || [];
  const mapped = keys.map((k: any) => {
    const start = k.startDate || k.createdAt?.split('T')[0] || new Date().toISOString().split('T')[0];
    const dur = k.durationDays !== undefined ? Number(k.durationDays) : 30;
    const end = k.endDate || (() => {
      const d = new Date(start);
      d.setDate(d.getDate() + dur);
      return d.toISOString().split('T')[0];
    })();
    return {
      ...k,
      durationDays: dur,
      startDate: start,
      endDate: end
    };
  });
  res.json(mapped);
});

app.post("/api/ai-coach/generate-key", (req, res) => {
  try {
    const settings = readSettings();
    if (!settings.aiCoachKeys) {
      settings.aiCoachKeys = [];
    }
    
    // Generate a secure unique key
    let newKey = "";
    let isUnique = false;
    while (!isUnique) {
      newKey = generateRandomKey();
      isUnique = !settings.aiCoachKeys.some((k: any) => k.key === newKey);
    }
    
    const { durationDays, startDate, endDate } = req.body;
    
    const defaultStart = startDate || new Date().toISOString().split('T')[0];
    const defaultEnd = endDate || (() => {
      const d = new Date(defaultStart);
      d.setDate(d.getDate() + (Number(durationDays) || 30));
      return d.toISOString().split('T')[0];
    })();

    const keyObject = {
      key: newKey,
      isUsed: false,
      usedBy: null,
      usedAt: null,
      createdAt: new Date().toISOString(),
      durationDays: Number(durationDays) || 30,
      startDate: defaultStart,
      endDate: defaultEnd
    };
    
    settings.aiCoachKeys.push(keyObject);
    writeSettings(settings);
    
    res.json({ success: true, key: keyObject });
  } catch (e: any) {
    res.status(500).json({ error: "Failed to generate key: " + e.message });
  }
});

app.post("/api/ai-coach/keys/:key/edit", (req, res) => {
  try {
    const keyToEdit = req.params.key;
    const { durationDays, startDate, endDate, isUsed } = req.body;
    const settings = readSettings();
    if (!settings.aiCoachKeys) {
      settings.aiCoachKeys = [];
    }
    const keyIndex = settings.aiCoachKeys.findIndex((k: any) => k.key === keyToEdit);
    if (keyIndex === -1) {
      return res.status(404).json({ error: "الكود غير موجود." });
    }

    const k = settings.aiCoachKeys[keyIndex];
    if (durationDays !== undefined) k.durationDays = Number(durationDays);
    if (startDate !== undefined) k.startDate = startDate;
    if (endDate !== undefined) k.endDate = endDate;
    if (isUsed !== undefined) k.isUsed = !!isUsed;

    writeSettings(settings);
    res.json({ success: true, key: k });
  } catch (e: any) {
    res.status(500).json({ error: "Failed to edit key: " + e.message });
  }
});

app.post("/api/ai-coach/activate", (req, res) => {
  try {
    const { key, studentPhone } = req.body;
    if (!key) {
      return res.status(400).json({ error: "الرجاء إدخال كود التفعيل" });
    }
    
    const settings = readSettings();
    const keys = settings.aiCoachKeys || [];
    const keyIndex = keys.findIndex((k: any) => k.key.toUpperCase() === key.trim().toUpperCase());
    
    if (keyIndex === -1) {
      return res.status(400).json({ error: "كود التفعيل غير صالح. الرجاء التأكد من الكود المكتوب." });
    }
    
    const keyObj = keys[keyIndex];
    if (keyObj.isUsed) {
      return res.status(400).json({ error: "هذا الكود تم استخدامه مسبقاً لتفعيل الخدمة." });
    }
    
    // Mark key as used
    keyObj.isUsed = true;
    keyObj.usedBy = studentPhone || "مجهول";
    keyObj.usedAt = new Date().toISOString();
    
    settings.aiCoachKeys = keys;
    writeSettings(settings);
    
    // Update student progress database
    if (studentPhone) {
      const students = readStudents();
      const studentIndex = students.findIndex((s: any) => s.phone === studentPhone);
      if (studentIndex >= 0) {
        students[studentIndex].aiCoachActivated = true;
        
        // Store AI Coach specific validity dates separately from platform subscription
        const start = keyObj.startDate || new Date().toISOString().split('T')[0];
        const dur = Number(keyObj.durationDays) || 30;
        const end = keyObj.endDate || (() => {
          const d = new Date(start);
          d.setDate(d.getDate() + dur);
          return d.toISOString().split('T')[0];
        })();
        
        students[studentIndex].aiCoachStartDate = start;
        students[studentIndex].aiCoachEndDate = end;
        
        writeStudents(students);

        return res.json({ 
          success: true, 
          message: "تم تفعيل مستشار الذكاء الاصطناعي بنجاح! 🎉",
          aiCoachStartDate: start,
          aiCoachEndDate: end
        });
      }
    }
    
    res.json({ success: true, message: "تم تفعيل مستشار الذكاء الاصطناعي بنجاح! 🎉" });
  } catch (e: any) {
    res.status(500).json({ error: "حدث خطأ أثناء التفعيل: " + e.message });
  }
});

app.post("/api/ai-coach/keys/delete", (req, res) => {
  try {
    const keyToDelete = (req.body.key || "").toString().trim().toUpperCase();
    if (!keyToDelete) {
      return res.status(400).json({ error: "الرجاء تحديد كود التفعيل المراد حذفه" });
    }
    const settings = readSettings();
    if (settings.aiCoachKeys) {
      settings.aiCoachKeys = settings.aiCoachKeys.filter(
        (k: any) => (k.key || "").toString().trim().toUpperCase() !== keyToDelete
      );
      writeSettings(settings);
    }
    res.json({ success: true, message: "تم حذف الكود بنجاح" });
  } catch (e: any) {
    res.status(500).json({ error: "فشل حذف الكود: " + e.message });
  }
});

